import heapq

def match(orders):
    buy_heap = []   # entries: (-price, seq, id)  -- max-price first, then earliest seq
    sell_heap = []  # entries: (price, seq, id)    -- min-price first, then earliest seq
    book = {}       # id -> dict(side, price, qty, seq, active)
    trades = []
    seq = 0

    for order in orders:
        seq += 1
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            info = book.get(oid)
            if info is not None and info['active'] and info['qty'] > 0:
                info['active'] = False
            continue

        oid = order[1]
        side = order[2]

        if typ == 'market':
            price = None
            qty = order[3]
        else:
            price = order[3]
            qty = order[4]

        remaining = qty

        if side == 'buy':
            heap = sell_heap
        else:
            heap = buy_heap

        while remaining > 0 and heap:
            if side == 'buy':
                top_price, top_seq, top_id = heap[0]
            else:
                neg_price, top_seq, top_id = heap[0]
                top_price = -neg_price

            info = book.get(top_id)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(heap)
                continue

            if typ != 'market':
                if side == 'buy' and top_price > price:
                    break
                if side == 'sell' and top_price < price:
                    break

            trade_qty = min(remaining, info['qty'])

            if side == 'buy':
                trades.append([oid, top_id, top_price, trade_qty])
            else:
                trades.append([top_id, oid, top_price, trade_qty])

            remaining -= trade_qty
            info['qty'] -= trade_qty

            if info['qty'] == 0:
                info['active'] = False
                heapq.heappop(heap)

        if typ == 'limit':
            if remaining > 0:
                book[oid] = {'side': side, 'price': price, 'qty': remaining, 'seq': seq, 'active': True}
                if side == 'buy':
                    heapq.heappush(buy_heap, (-price, seq, oid))
                else:
                    heapq.heappush(sell_heap, (price, seq, oid))
            else:
                book[oid] = {'side': side, 'price': price, 'qty': 0, 'seq': seq, 'active': False}
        # ioc and market: discard remainder, do nothing further

    return trades

